<script>
 import {onMount,onDestroy,untrack} from 'svelte';
 let {index,code,language='pt',active=true}=$props();
 const config=$derived(JSON.parse(code));
 const copy={
 pt:{label:'SIMULAÇÃO LOCAL',title:['Seu fluxo, em movimento.','Os dados encontrando seu lugar.'],sub:['Acompanhe o que sua regra faz com uma mensagem recebida.','Acompanhe a transformação entre o formulário e o CRM.'],steps:[['Mensagem recebida','Regra aplicada','Ação executada','Conversa atualizada'],['Formulário recebido','Campos mapeados','Registro criado','Sistemas sincronizados']],play:'Continuar',pause:'Pausar',replay:'Repetir simulação',next:'Próxima etapa',wait:'Aguardando o fluxo…',customer:'Cliente de exemplo',business:'loui / atendimento',typing:'Preparando resposta…',reply:'Olá! Recebemos sua mensagem. Nossa equipe vai continuar seu atendimento.',queued:'Conversa encaminhada à equipe. Nenhuma resposta automática enviada.',high:'Prioridade alta',normal:'Prioridade normal',rule:'Sua regra',request:'Mensagem recebida',source:'Formulário do site',destination:'CRM de demonstração',mapped:'Mapeamento aplicado',received:'Nova solicitação',stage:'Etapa',name:'Nome',pending:'Aguardando registro',done:'Simulação concluída',note:'Nada foi enviado ao WhatsApp ou a um CRM real. Você está acompanhando uma simulação no navegador.'},
 en:{label:'LOCAL SIMULATION',title:['Your workflow in motion.','Data finding its place.'],sub:['Follow your rule as it processes an incoming message.','Follow the transformation from website form to CRM.'],steps:[['Message received','Rule applied','Action executed','Conversation updated'],['Form received','Fields mapped','Record created','Systems synchronized']],play:'Continue',pause:'Pause',replay:'Replay simulation',next:'Next step',wait:'Waiting for the workflow…',customer:'Example customer',business:'loui / support',typing:'Preparing reply…',reply:'Hi! We received your message. Our team will continue the conversation.',queued:'Conversation routed to the team. No automatic reply sent.',high:'High priority',normal:'Normal priority',rule:'Your rule',request:'Incoming message',source:'Website form',destination:'Demo CRM',mapped:'Mapping applied',received:'New request',stage:'Stage',name:'Name',pending:'Waiting for record',done:'Simulation complete',note:'Nothing was sent to WhatsApp or a real CRM. This simulation runs in your browser.'},
 es:{label:'SIMULACIÓN LOCAL',title:['Tu flujo en movimiento.','Los datos encontrando su lugar.'],sub:['Observa cómo tu regla procesa un mensaje recibido.','Sigue la transformación del formulario al CRM.'],steps:[['Mensaje recibido','Regla aplicada','Acción ejecutada','Conversación actualizada'],['Formulario recibido','Campos relacionados','Registro creado','Sistemas sincronizados']],play:'Continuar',pause:'Pausar',replay:'Repetir simulación',next:'Siguiente paso',wait:'Esperando el flujo…',customer:'Cliente de ejemplo',business:'loui / atención',typing:'Preparando respuesta…',reply:'¡Hola! Recibimos tu mensaje. Nuestro equipo continuará la conversación.',queued:'Conversación enviada al equipo. Sin respuesta automática.',high:'Prioridad alta',normal:'Prioridad normal',rule:'Tu regla',request:'Mensaje recibido',source:'Formulario del sitio',destination:'CRM de demostración',mapped:'Mapeo aplicado',received:'Nueva solicitud',stage:'Etapa',name:'Nombre',pending:'Esperando registro',done:'Simulación completada',note:'No se envió nada a WhatsApp ni a un CRM real. Esta simulación ocurre en tu navegador.'}
 };
 const c=$derived(copy[language]||copy.pt);
 const source=$derived({nome:'Ana Costa',empresa:'Ateliê Horizonte',etapa:language==='en'?'First conversation':language==='es'?'Primera conversación':'Primeira conversa',origem:'Website'});
 let inspected=$state(0),attempt=$state(1);
 const t=(pt,en,es)=>language==='en'?en:language==='es'?es:pt;
 function inspect(n){inspected=n;}
 function resend(){attempt++;step=0;playing=!reduced;schedule();}
 let step=$state(0),playing=$state(false),timer,reduced=false;
 $effect(()=>{const enabled=active;untrack(()=>{playing=enabled&&!matchMedia('(prefers-reduced-motion: reduce)').matches;schedule();});});
 const final=4;
 function schedule(){clearTimeout(timer);if(playing&&step<final)timer=setTimeout(()=>{step++;if(step===final)playing=false;else schedule();},1400);}
 function toggle(){playing=!playing;schedule();}
 function next(){playing=false;clearTimeout(timer);step=Math.min(final,step+1);}
 function replay(){clearTimeout(timer);step=0;playing=!reduced;schedule();}
 onMount(()=>{const media=matchMedia('(prefers-reduced-motion: reduce)');reduced=media.matches;playing=active&&!reduced;schedule();const change=()=>{reduced=media.matches;if(reduced){playing=false;clearTimeout(timer);}};media.addEventListener('change',change);return()=>media.removeEventListener('change',change);});
 onDestroy(()=>clearTimeout(timer));
</script>
<section class="process-simulation" class:integration-app={index===2} data-step={step}>
 <header class="operations-bar"><div class="operations-brand"><span class="operations-mark" aria-hidden="true">{index===1?'a':'s'}</span><strong>{index===1?t('atende','attend','atiende'):t('sincronia','sync','sincronía')}</strong><span>{index===1?t('Mesa de atendimento','Support desk','Mesa de atención'):t('Central de integrações','Integration center','Centro de integraciones')}</span></div><span class="operations-demo">{t('Ambiente demonstrativo','Demo environment','Entorno de demostración')}</span></header>
 <header class="simulation-heading"><div><p>{index===1?t('Atendimento / Fluxo de entrada','Support / Incoming workflow','Atención / Flujo de entrada'):t('Comércio / Pedidos e contatos','Commerce / Orders and contacts','Comercio / Pedidos y contactos')}</p><h1>{index===1?t('Cada conversa, um próximo passo.','Every conversation, a next step.','Cada conversación, un siguiente paso.'):t('Um pedido. Dois sistemas conectados.','One order. Two connected systems.','Un pedido. Dos sistemas conectados.')}</h1></div><div class="simulation-controls">{#if step<final}<button type="button" class="simulation-toggle" aria-pressed={playing} onclick={toggle}>{playing?c.pause:c.play}</button><button type="button" class="simulation-next" onclick={next}>{c.next}</button>{/if}<button type="button" class="simulation-replay" onclick={()=>{attempt=1;inspected=0;replay();}}>{c.replay}</button></div></header>
 {#if index===1}
 <div class="support-workspace">
  <aside class="support-inbox"><h2>{t('Conversas','Conversations','Conversaciones')}<span>1</span></h2><div class="inbox-filter">{t('Caixa de entrada','Inbox','Bandeja de entrada')}</div><div class="inbox-selected"><span class="person-avatar">A</span><div><strong>Ana / {t('exemplo','sample','ejemplo')}</strong><p>{step>=1?config.request:c.wait}</p></div><i class:unread={step>=1&&step<4}></i></div><p class="inbox-note">{t('A mensagem e a prioridade vêm do código que você completou.','The message and priority come from the code you completed.','El mensaje y la prioridad vienen del código que completaste.')}</p><div class="inbox-status"><span></span>{t('Execução local','Local execution','Ejecución local')}</div></aside>
  <section class="chat-preview"><header><span class="person-avatar">A</span><div><strong>Ana Costa</strong><small>WhatsApp · {t('Conversa de exemplo','Sample conversation','Conversación de ejemplo')}</small></div><span class="chat-label">{step===4?t('Tratada','Handled','Atendida'):t('Em atendimento','In progress','En atención')}</span></header><div class="chat-messages"><div class="conversation-date">{t('Hoje · demonstração','Today · demo','Hoy · demo')}</div>
  {#if step===0}<div class="chat-empty"><svg viewBox="0 0 48 48" fill="none" stroke="currentColor" aria-hidden="true"><path d="M9 9h30v24H22L9 41V9Z" stroke-width="1.5"/><path d="M17 18h14M17 24h9"/></svg><p>{t('Seu fluxo está pronto para receber a mensagem.','Your workflow is ready to receive the message.','Tu flujo está listo para recibir el mensaje.')}</p></div>{/if}
  {#if step>=1}<div class="chat-bubble incoming"><p>{config.request}</p><time>09:41</time></div>{/if}
  {#if step>=2}<div class="chat-event">{config.priority==='alta'?c.high:c.normal} · {t('Regra aplicada','Rule applied','Regla aplicada')}</div>{/if}
  {#if step===3&&config.action==='responder'}<div class="chat-typing">{c.typing}<span aria-hidden="true">•••</span></div>{/if}
  {#if step>=4&&config.action==='responder'}<div class="chat-bubble outgoing"><small>{t('Resposta automática simulada','Simulated automatic reply','Respuesta automática simulada')}</small><p>{c.reply}</p><time>09:41 <svg viewBox="0 0 20 12" aria-hidden="true"><path d="m1 5 4 4L13 1M8 7l2 2 8-8" fill="none" stroke="currentColor" stroke-width="1.5"/></svg></time></div>{/if}
  {#if step>=3&&config.action==='organizar'}<div class="chat-routing"><strong>{t('Equipe notificada','Team notified','Equipo notificado')}</strong><p>{c.queued}</p></div>{/if}
  </div><div class="chat-composer"><span>{t('O fluxo controla esta conversa','The workflow controls this conversation','El flujo controla esta conversación')}</span><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" aria-hidden="true"><path d="m4 4 17 8-17 8 3-8-3-8Zm3 8h14"/></svg></div></section>
  <aside class="execution-inspector"><header><h2>{t('Execução do fluxo','Workflow execution','Ejecución del flujo')}</h2><span class:running={playing}>{step===4?c.done:playing?t('Em execução','Running','En ejecución'):t('Pausada','Paused','Pausada')}</span></header><ol class="execution-nodes">{#each c.steps[0] as label,i}<li class:reached={step>i} class:inspect-selected={inspected===i}><button type="button" onclick={()=>inspect(i)} aria-pressed={inspected===i}><span class="node-dot">{i+1}</span><span>{label}<small>{step>i?t('Concluído','Completed','Completado'):t('Aguardando','Waiting','En espera')}</small></span></button></li>{/each}</ol><section class="node-detail"><h3>{c.steps[0][inspected]}</h3><p>{step>inspected?t('Saída desta etapa','This step output','Salida de esta etapa'):t('Esta etapa ainda não foi executada.','This step has not run yet.','Esta etapa todavía no se ha ejecutado.')}</p>{#if step>inspected}<code>{inspected===0?config.request:inspected===1?'priority: '+config.priority:config.action==='responder'?'message.reply':'team.assign'}</code>{/if}</section></aside>
 </div>
 {:else}
 <div class="integration-connection"><span class="connector-brand">loja / <strong>{t('Pedidos','Orders','Pedidos')}</strong></span><span class="connection-line" class:connected={step>=4}></span><span>{t('Conexão de demonstração','Demo connection','Conexión de demostración')}</span><span class="connection-line" class:connected={step>=4}></span><span class="connector-brand">crm / <strong>{t('Contatos','Contacts','Contactos')}</strong></span></div>
 <div class="integration-workspace">
  <section class="order-document"><header><div><span>{t('Pedido de exemplo','Sample order','Pedido de ejemplo')}</span><h2>#1042</h2></div><span class="order-status">{step>=1?t('Recebido','Received','Recibido'):t('Aguardando','Waiting','Esperando')}</span></header><div class="order-item"><div class="order-product" aria-hidden="true"><svg viewBox="0 0 70 70" fill="none"><path d="M24 14h22l5 39H19l5-39Z" fill="#d5b69b"/><path d="M28 14v-2a7 7 0 0 1 14 0v2" stroke="#6a5140" stroke-width="3"/><path d="M24 26h22M24 31h15" stroke="#a18168"/></svg></div><div><strong>{t('Bolsa de algodão','Cotton tote','Bolsa de algodón')}</strong><span>{t('Natural / 1 unidade','Natural / 1 item','Natural / 1 unidad')}</span></div><b>R$ 89</b></div><h3>{t('Dados recebidos','Received data','Datos recibidos')}</h3><div class="source-fields">{#each Object.entries(source) as [key,value]}<button type="button" disabled={key!==config.name&&key!==config.stage} class:field-selected={key===(inspected===0?config.name:config.stage)} onclick={()=>inspected=key===config.name?0:key===config.stage?1:0} aria-pressed={key===(inspected===0?config.name:config.stage)}><code>{key}</code><strong>{value}</strong></button>{/each}</div><p>{t('O pedido permanece igual. Seu código decide quais campos chegam ao CRM.','The order stays the same. Your code decides which fields reach the CRM.','El pedido permanece igual. Tu código decide qué campos llegan al CRM.')}</p></section>
  <section class="mapping-console"><h2>{t('Seu mapeamento','Your mapping','Tu mapeo')}</h2><p>{t('Selecione um par para acompanhar a transformação.','Select a pair to follow the transformation.','Selecciona un par para seguir la transformación.')}</p><div class="mapping-pairs">{#each [[config.name,'name'],[config.stage,'stage']] as pair,i}<button type="button" class:pair-selected={inspected===i} onclick={()=>inspected=i} aria-pressed={inspected===i}><code>{pair[0]}</code><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" aria-hidden="true"><path d="M4 12h15m-5-5 5 5-5 5"/></svg><code>{pair[1]}</code></button>{/each}</div><div class="mapping-result" class:transformed={step>=2}><span>{t('Valor transformado','Transformed value','Valor transformado')}</span><strong>{step>=2?source[inspected===0?config.name:config.stage]:c.wait}</strong></div><div class="payload-view"><span>{t('Payload de saída','Output payload','Payload de salida')}</span><pre>{step>=2?JSON.stringify({order_id:1042,name:source[config.name],stage:source[config.stage]},null,2):'{ ... }'}</pre></div></section>
  <section class="crm-destination"><header><h2>{t('Relacionamento','Relationships','Relaciones')}</h2><span>{step>=3?'1':'0'} {t('registro','record','registro')}</span></header><div class="crm-column-heading"><span></span>{t('Novos contatos','New contacts','Nuevos contactos')}</div>{#if step>=3}<article class="crm-record"><div class="crm-person"><span class="person-avatar">{source[config.name].slice(0,1)}</span><div><h3 class:highlighted={inspected===0}>{source[config.name]}</h3><small>{t('Origem: pedido #1042','Source: order #1042','Origen: pedido #1042')}</small></div></div><dl><div class:highlighted={inspected===1}><dt>{c.stage}</dt><dd>{source[config.stage]}</dd></div><div><dt>{t('Último pedido','Latest order','Último pedido')}</dt><dd>R$ 89</dd></div></dl><p>{attempt>1?t('Registro atualizado. Nenhum contato duplicado.','Record updated. No duplicate contact.','Registro actualizado. Sin contacto duplicado.'):t('Contato criado com o seu mapeamento.','Contact created using your mapping.','Contacto creado con tu mapeo.')}</p><span class="record-origin">order_id: 1042</span></article>{:else}<div class="crm-placeholder"><svg viewBox="0 0 48 48" fill="none" stroke="currentColor" aria-hidden="true"><rect x="8" y="8" width="32" height="32" rx="4"/><path d="M24 17v14m-7-7h14"/></svg><p>{c.pending}</p></div>{/if}{#if step===4}<button class="integration-resend" type="button" onclick={resend}>{t('Simular reenvio do pedido','Simulate sending again','Simular reenvío del pedido')}</button>{/if}</section>
 </div>
 <ol class="integration-events">{#each c.steps[1] as label,i}<li class:reached={step>i}><span>{i+1}</span>{label}</li>{/each}</ol>
 {/if}
 <div class="simulation-bottom"><p class="simulation-live-status" role="status">{step===0?c.wait:step===final?c.done:c.steps[index-1][step-1]}</p><p class="simulation-note">{c.note}</p></div>
</section>
